(()=>{'use strict';const cfg=window.zohoPaymentsEddConfig;if(!cfg)return;let busy=false;const setSt=(t,b,btn)=>{const el=document.getElementById('zoho-edd-status-container');if(!el)return;el.hidden=false;el.innerHTML='<strong>'+t+'</strong><p style="margin:4px 0 0">'+b+'</p>';if(btn){const x=document.createElement('button');x.type='button';x.className='button';x.style.marginTop='8px';x.textContent=cfg.i18n.checkStatusBtn;x.onclick=btn;el.appendChild(x)}},post=async d=>{const r=await fetch(cfg.ajaxUrl,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(d)});return r.json().catch(()=>({}))},poll=async(oid,ok,tries=12)=>{for(let i=0;i<tries;i++){const r=await post({action:'zoho_payments_edd_order_status',nonce:cfg.nonce,order_id:oid,order_key:ok});if(r?.success&&r.data?.status==='complete'&&r.data?.redirect_url)return location.assign(r.data.redirect_url);if(r?.success&&r.data?.status==='failed')return setSt(cfg.i18n.failedTitle,cfg.i18n.failedBody);await new Promise(s=>setTimeout(s,2000))}setSt(cfg.i18n.delayedTitle,cfg.i18n.delayedBody,()=>poll(oid,ok,6))},getGw=form=>form.querySelector('input[name="edd-gateway"]:checked,input[name="edd-gateway"][type="hidden"]')?.value,startCheckout=async form=>{if(busy)return;busy=true;const btn=form.querySelector('#edd-purchase-button');if(btn)btn.disabled=true;setSt(cfg.i18n.processingTitle,cfg.i18n.initializing);try{const fd=new FormData(form),p={action:'zoho_payments_edd_create_session',nonce:cfg.nonce,edd_email:fd.get('edd_email')||'',edd_first:fd.get('edd_first')||'',edd_last:fd.get('edd_last')||'',edd_phone:fd.get('edd_phone')||''},sr=await post(p);if(!sr?.success||!sr.data?.payments_session_id)throw new Error(sr?.data?.message||cfg.i18n.genericError);if(!window.ZPayments)throw new Error(cfg.i18n.widgetUnavailable);const d=sr.data,w=new window.ZPayments({account_id:cfg.accountId,domain:cfg.domain||'IN',otherOptions:{api_key:cfg.apiKey,...(cfg.isTestMode?{is_test_mode:true}:{})}});try{await w.requestPaymentMethod({payments_session_id:d.payments_session_id,payment_session_id:d.payments_session_id,amount:d.amount,currency_code:d.currency_code,currency_symbol:d.currency_symbol,description:d.description,reference_number:d.reference_number,address:d.address});try{await w.close()}catch(_){}setSt(cfg.i18n.processingTitle,cfg.i18n.processingBody);await poll(d.order_id,d.order_key)}catch(we){try{await w.close()}catch(_){}if(we?.code==='widget_closed')setSt(cfg.i18n.widgetClosedTitle,cfg.i18n.widgetClosed);else setSt(cfg.i18n.failedTitle,we?.message||cfg.i18n.failedBody)}}catch(err){setSt(cfg.i18n.failedTitle,err?.message||cfg.i18n.genericError)}finally{busy=false;if(btn)btn.disabled=false}};document.addEventListener('click',e=>{const t=e.target&&e.target.closest?e.target.closest('#edd-purchase-button,#edd_purchase_form input[type="submit"],#edd_purchase_form button[type="submit"]'):null;if(!t)return;const form=t.form||t.closest('#edd_purchase_form');if(!form||form.id!=='edd_purchase_form'||getGw(form)!==cfg.gatewayId)return;e.preventDefault();e.stopImmediatePropagation();if(typeof form.reportValidity==='function'&&!form.reportValidity())return;startCheckout(form)},true);document.addEventListener('submit',e=>{const form=e.target;if(!form||form.id!=='edd_purchase_form'||getGw(form)!==cfg.gatewayId)return;e.preventDefault();e.stopImmediatePropagation();startCheckout(form)},true);if(window.jQuery){window.jQuery(document).on('submit','#edd_purchase_form',e=>{const form=e.currentTarget;if(!form||getGw(form)!==cfg.gatewayId)return;e.preventDefault();e.stopImmediatePropagation();startCheckout(form)})}})();